1	import { useState, useEffect } from 'react';
2	import useJobStream from './hooks/useJobStream.js';
3	import { runStage, readVaultFile, ConflictError } from './api.js';
4	import { announceStart, announceDone, announceFail } from './jobActivity.js';
5	import MarkdownViewer from './MarkdownViewer.jsx';
6	import OutputBrowser from './OutputBrowser.jsx';
7	import VaultPicker from './VaultPicker.jsx';
8	import Icon from './Icons.jsx';
9	
10	// Ordered chain. `key` is the runStage() endpoint key (see api.js STAGE_ENDPOINTS).
11	const STEPS = [
12	  { id: "trends",    key: "trends",     label: "Trends",     color: "var(--stage-trends)",       gate: "pick" },
13	  { id: "research",  key: "research",   label: "Research",   color: "var(--stage-research)",     gate: "approve" },
14	  { id: "ideation",  key: "ideation",   label: "Ideation",   color: "var(--stage-ideation)",     gate: "pick" },
15	  { id: "hook",      key: "hooks",      label: "Hook",       color: "var(--stage-hooks)",        gate: "approve" },
16	  { id: "outline",   key: "outline",    label: "Outline",    color: "var(--stage-distribution)", gate: "approve" },
17	  { id: "title",     key: "title",      label: "Title",      color: "var(--stage-distribution)", gate: "pick" },
18	  { id: "cascade",   key: "cascade",    label: "Cascade",    color: "var(--stage-distribution)", gate: "approve" },
19	  { id: "shortform", key: "short-form", label: "Short-form", color: "var(--stage-distribution)", gate: "terminal" },
20	];
21	
22	const idx = (id) => STEPS.findIndex((s) => s.id === id);
23	
24	// Whether the active step already has the output/gate it needs to render its
25	// selection UI. Trends is always ready (its gate is the vault picker itself).
26	function gateReady(stepId, picks, results) {
27	  switch (stepId) {
28	    case "trends": return true;
29	    case "research": return true; // config form is the gate; ApproveGate shows once a brief exists
30	    case "ideation": return !!results.ideaSrc;
31	    case "hook": return !!picks.hooksPath;
32	    case "outline": return !!picks.outlinePath;
33	    case "title": return !!results.titleSrc;
34	    case "cascade": return !!results.cascade;
35	    default: return false;
36	  }
37	}
38	
39	// --- parsing: only the field the next stage consumes (advisor: minimal surface) ---
40	function parseIdeas(md) {
41	  const out = [];
42	  const re = /^#{2,3}\s+Rank\s+\d+\s*[—–-]\s*(.+?)\s*$/gm;
43	  let m;
44	  while ((m = re.exec(md))) out.push(m[1].trim());
45	  return out;
46	}
47	function parseTitles(md) {
48	  const body = md.split(/^###\s+Thumbnail/m)[0];
49	  const out = [];
50	  const re = /^[-*]\s*\*\*(.+?)\*\*/gm;
51	  let m;
52	  while ((m = re.exec(body))) {
53	    const t = m[1].trim();
54	    if (!/^Tier-\d/i.test(t) && !t.endsWith(":")) out.push(t);
55	  }
56	  return [...new Set(out)];
57	}
58	
59	export default function FullPipelinePage({ onBack }) {
60	  const [seed, setSeed] = useState("");
61	  const [activeId, setActiveId] = useState("trends");
62	  const [phase, setPhase] = useState("idle"); // idle | running | review | done
63	  const [runningStage, setRunningStage] = useState(null); // step id of in-flight job
64	  const [stageError, setStageError] = useState(null);
65	  const [refreshKey, setRefreshKey] = useState(0);
66	  const [picks, setPicks] = useState({
67	    trendPath: null, briefPath: null, ideaTitle: null,
68	    hooksPath: null, outlinePath: null, titleString: null,
69	  });
70	  const [results, setResults] = useState({ ideaSrc: null, titleSrc: null, cascade: null, short: null });
71	  const [research, setResearch] = useState({
72	    niche: "", mode: "deep", targetLength: "", tone: "", audience: "", banned: "",
73	  });
74	
75	  const [jobId, setJobId] = useState(null);
76	  const jobStream = useJobStream(jobId);
77	
78	  // --- launch a stage; selecting IS the trigger for the next stage ---
79	  async function launch(step, body) {
80	    setStageError(null);
81	    try {
82	      announceStart(step.key);
83	      const { job_id } = await runStage(step.key, body);
84	      setRunningStage(step.id);
85	      setActiveId(step.id);
86	      setPhase("running");
87	      setJobId(job_id);
88	    } catch (e) {
89	      announceFail(step.key);
90	      setStageError(
91	        e instanceof ConflictError
92	          ? "Another job is already running — wait for it to finish, then retry."
93	          : e.message
94	      );
95	      setPhase(step.id === "trends" ? "idle" : "review");
96	    }
97	  }
98	
99	  // --- driver: react to the in-flight job finishing ---
100	  /* eslint-disable react-hooks/set-state-in-effect */
101	  useEffect(() => {
102	    if (!runningStage) return;
103	    const step = STEPS[idx(runningStage)];
104	    if (jobStream.status === "completed") {
105	      announceDone(step.key);
106	      const res = jobStream.result || {};
107	      const path = res.primary_path || "";
108	      if (runningStage === "trends") { setRefreshKey((k) => k + 1); setPhase("idle"); }
109	      else if (runningStage === "research") { setPicks((p) => ({ ...p, briefPath: path })); setPhase("review"); }
110	      else if (runningStage === "ideation") { setResults((r) => ({ ...r, ideaSrc: path })); setPhase("review"); }
111	      else if (runningStage === "hook") { setPicks((p) => ({ ...p, hooksPath: path })); setPhase("review"); }
112	      else if (runningStage === "outline") { setPicks((p) => ({ ...p, outlinePath: path })); setPhase("review"); }
113	      else if (runningStage === "title") { setResults((r) => ({ ...r, titleSrc: path })); setPhase("review"); }
114	      else if (runningStage === "cascade") { setResults((r) => ({ ...r, cascade: res })); setPhase("review"); }
115	      else if (runningStage === "shortform") { setResults((r) => ({ ...r, short: res })); setPhase("done"); }
116	      setRunningStage(null);
117	    } else if (jobStream.status === "failed") {
118	      announceFail(step.key);
119	      setStageError(jobStream.error || "Stage failed");
120	      setRunningStage(null);
121	      setPhase("review");
122	    }
123	  }, [jobStream.status]);
124	  /* eslint-enable react-hooks/set-state-in-effect */
125	
126	  // --- gate actions (each advances + auto-runs the next stage) ---
127	  // Picking a trend no longer auto-runs research — it opens the Research config gate.
128	  const pickTrend = (path) => {
129	    setPicks((p) => ({ ...p, trendPath: path }));
130	    setResearch((r) => ({ ...r, niche: r.niche || seed }));
131	    setStageError(null);
132	    setActiveId("research");
133	    setPhase("review");
134	  };
135	  const runResearch = () =>
136	    launch(STEPS[idx("research")], {
137	      niche: research.niche.trim(),
138	      repos: [],
139	      mode: research.mode,
140	      trend_repo: picks.trendPath,
141	      target_length: research.targetLength ? Number(research.targetLength) : null,
142	      tone: research.tone.trim(),
143	      audience: research.audience.trim(),
144	      banned_phrases: research.banned.split(",").map((s) => s.trim()).filter(Boolean),
145	    });
146	  const refreshTrends = () => launch(STEPS[idx("trends")], { space: seed });
147	  const approveResearch = () =>
148	    launch(STEPS[idx("ideation")], { topic: seed, research_file: picks.briefPath, no_trends: false });
149	  const pickIdea = (title) => {
150	    setPicks((p) => ({ ...p, ideaTitle: title }));
151	    launch(STEPS[idx("hook")], {
152	      topic: title, platform: "yt-long", audience: "", format: "medium",
153	      research_file: picks.briefPath, no_polish: false,
154	    });
155	  };
156	  const approveHooks = () =>
157	    launch(STEPS[idx("outline")], {
158	      topic: picks.ideaTitle, hook_path: picks.hooksPath,
159	      length: 8, platform: "yt-long", no_polish: false,
160	    });
161	  const approveOutline = () =>
162	    launch(STEPS[idx("title")], { concept: picks.ideaTitle, outline_file: picks.outlinePath });
163	  const pickTitle = (str) => {
164	    setPicks((p) => ({ ...p, titleString: str }));
165	    launch(STEPS[idx("cascade")], {
166	      research_file: picks.briefPath, outline_file: picks.outlinePath, title: str, youtube_url: "",
167	    });
168	  };
169	  const approveCascade = () =>
170	    launch(STEPS[idx("shortform")], {
171	      research_file: picks.briefPath, outline_file: picks.outlinePath,
172	      title: picks.titleString, youtube_url: "",
173	    });
174	
175	  // retry the stage that just failed (re-issue with the same threaded inputs)
176	  const retry = () => {
177	    const map = {
178	      research: runResearch,
179	      ideation: approveResearch,
180	      hook: () => pickIdea(picks.ideaTitle),
181	      outline: approveHooks,
182	      title: approveOutline,
183	      cascade: () => pickTitle(picks.titleString),
184	      shortform: approveCascade,
185	      trends: refreshTrends,
186	    };
187	    (map[activeId] || (() => {}))();
188	  };
189	
190	  const activeIndex = idx(activeId);
191	  const seedReady = seed.trim().length > 0;
192	
193	  return (
194	    <div data-screen-label="Full Pipeline">
195	      <header className="page-header">
196	        <div>
197	          <h1 className="page-title">Full Pipeline</h1>
198	          <p className="page-subtitle">
199	            Run the whole chain end-to-end — trends → research → ideation → hook → outline → title → cascade → short-form.
200	            Review each step, select, and the next one runs automatically.
201	          </p>
202	        </div>
203	        {onBack && <button className="btn btn-ghost" onClick={onBack}>← Dashboard</button>}
204	      </header>
205	
206	      <div className="fp-seed">
207	        <label className="fp-seed-label">Niche / space</label>
208	        <input
209	          className="fp-seed-input"
210	          placeholder="e.g. local-first AI tooling for indie devs"
211	          value={seed}
212	          onChange={(e) => setSeed(e.target.value)}
213	          disabled={activeIndex > 0 || phase === "running"}
214	        />
215	      </div>
216	
217	      <div className="fp-stepper">
218	        {STEPS.map((step, i) => {
219	          const state =
220	            i < activeIndex ? "done" :
221	            i === activeIndex ? (phase === "done" ? "done" : "active") :
222	            "locked";
223	          const isRunning = runningStage === step.id || (i === activeIndex && phase === "running");
224	          return (
225	            <div
226	              key={step.id}
227	              className={`fp-step is-${state}` + (isRunning ? " is-running" : "")}
228	              style={{ "--stage-color": step.color }}
229	            >
230	              <div className="fp-step-head">
231	                <span className="fp-step-dot">{i + 1}</span>
232	                <span className="fp-step-label">{step.label}</span>
