237	
238	              {state === "active" && (
239	                <div className="fp-step-body">
240	                  {isRunning ? (
241	                    <pre className="fp-log">
242	                      {jobStream.lines.length ? jobStream.lines.join("\n") : "Starting…"}
243	                    </pre>
244	                  ) : (
245	                    <>
246	                      {stageError && <div className="fp-error-msg">{stageError}</div>}
247	                      {gateReady(step.id, picks, results) ? (
